union DGroupImage dgroup;
uint8_t ds_outside;

/* C cannot initialise a union through a byte array and keep a const master copy, so copy at startup. */
__attribute__((constructor)) static void dgroup_init(void) { memcpy(dgroup.raw, initial_image, DS_SIZE); }

void dgroup_reset(void) { memcpy(dgroup.raw, initial_image, DS_SIZE); }

int dgroup_load_game(const char *path)
{
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    size_t n = fread(dgroup.raw + SAVE_OFFSET, 1, SAVE_SIZE, f);
    fclose(f);
    return n == SAVE_SIZE ? 0 : -1;
}

int dgroup_save_game(const char *path)
{
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    size_t n = fwrite(dgroup.raw + SAVE_OFFSET, 1, SAVE_SIZE, f);
    fclose(f);
    return n == SAVE_SIZE ? 0 : -1;
}
